/* =========================================================
   REAL GOOGLE MAPS (iframe embed)
   - keyless by default (real Google tiles)
   - uses official Embed API when an API key is provided
   ========================================================= */
function RealMap({query,mode="roadmap",apiKey="",height=200,zoom=14}){
  let src;
  if(apiKey){
    const mt=mode==="satellite"?"satellite":"roadmap";
    src=`https://www.google.com/maps/embed/v1/place?key=${apiKey}&q=${encodeURIComponent(query)}&maptype=${mt}&zoom=${zoom}`;
  }else{
    const t=mode==="satellite"?"k":mode==="terrain"?"p":"m";
    src=`https://maps.google.com/maps?q=${encodeURIComponent(query)}&t=${t}&z=${zoom}&output=embed`;
  }
  return <iframe title="Google Map" src={src} style={{width:"100%",height,border:0,display:"block"}} loading="lazy" allowFullScreen referrerPolicy="no-referrer-when-downgrade"/>;
}


