function HubTab({t,theme,baseText,subText,currency}){
  const target=new Date("2026-08-15T19:00:00").getTime();
  const [now,setNow]=useState(Date.now());
  const [info,setInfo]=useState(false);
  const [addOpen,setAddOpen]=useState(false);
  const [draft,setDraft]=useState({title:"",venue:"",date:""});
  const [extraUpcoming,setExtraUpcoming]=useState([]);
  useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(id);},[]);
  const diff=Math.max(0,target-now);
  const d=Math.floor(diff/86400000),h=Math.floor(diff%86400000/3600000),m=Math.floor(diff%3600000/60000),s=Math.floor(diff%60000/1000);
  const units=[[d,t.hub_days],[h,t.hub_hours],[m,t.hub_mins],[s,t.hub_secs]];
  const addImgs=[CONCERT_IMG.festival,CONCERT_IMG.club,CONCERT_IMG.amber,CONCERT_IMG.blue];
  const addConcert=()=>{const tt=draft.title.trim();if(!tt)return;setExtraUpcoming(p=>[...p,{title:tt,venue:draft.venue.trim()||"Venue TBC",date:draft.date.trim()||"Date TBC",img:addImgs[p.length%addImgs.length]}]);setDraft({title:"",venue:"",date:""});setAddOpen(false);};
  const history=[
    {title:"Taylor Swift | The Eras Tour",sub:"Paris · La Défense Arena · Completed 10 May 2024",img:CONCERT_IMG.festival},
    {title:"TWICE <THIS IS FOR> WORLD TOUR IN SINGAPORE",sub:"National Stadium · Completed 11 & 12 October 2025",img:CONCERT_IMG.amber},
    {title:"ENHYPEN WORLD TOUR ‘WALK THE LINE’",sub:"London · The O2 · Completed August 2025",img:CONCERT_IMG.club},
  ];
  return (
    <div>
      <SectionTitle color={baseText}>{t.hub_title}</SectionTitle>
      <Card theme={theme} style={{background:theme.headerBg,border:`1.5px solid ${theme.accent}`}}>
        <p style={{fontSize:11,fontWeight:800,color:theme.headerText,letterSpacing:1,marginBottom:4}}>{t.hub_countdown.toUpperCase()}</p>
        <p style={{fontSize:13,fontWeight:700,color:theme.headerText,marginBottom:12,opacity:.9}}>Ariana Grande · The O2 Arena</p>
        <div style={{display:"flex",gap:8}}>
          {units.map(([v,l])=>(
            <div key={l} style={{flex:1,textAlign:"center",background:"rgba(0,0,0,.18)",borderRadius:12,padding:"10px 0"}}>
              <div style={{fontSize:24,fontWeight:900,color:"#fff",lineHeight:1}}>{String(v).padStart(2,"0")}</div>
              <div style={{fontSize:9,fontWeight:700,color:"rgba(255,255,255,.85)",marginTop:4}}>{l}</div>
            </div>
          ))}
        </div>
      </Card>

      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",margin:"4px 0 10px"}}>
        <p style={{fontSize:13,fontWeight:800,color:subText}}>{t.hub_upcoming}</p>
        <button onClick={()=>setAddOpen(!addOpen)} style={{border:"none",cursor:"pointer",background:theme.accent,color:theme.dark?"#06121F":"#fff",fontWeight:800,fontSize:11,padding:"6px 12px",borderRadius:20}}>{addOpen?"Close":"+ Add concert"}</button>
      </div>
      {addOpen&&(
        <Card theme={theme}>
          <input value={draft.title} onChange={(e)=>setDraft(p=>({...p,title:e.target.value}))} placeholder="Artist & tour" style={{...selectStyle(theme),marginBottom:8}}/>
          <input value={draft.venue} onChange={(e)=>setDraft(p=>({...p,venue:e.target.value}))} placeholder="City · Venue" style={{...selectStyle(theme),marginBottom:8}}/>
          <input value={draft.date} onChange={(e)=>setDraft(p=>({...p,date:e.target.value}))} placeholder="Date" style={{...selectStyle(theme),marginBottom:10}}/>
          <button onClick={addConcert} style={{width:"100%",border:"none",cursor:"pointer",background:theme.accent,color:theme.dark?"#06121F":"#fff",fontWeight:800,fontSize:12.5,padding:"11px",borderRadius:12}}>Add to upcoming</button>
        </Card>
      )}

      {/* primary upcoming with full ticket/venue info */}
      <Card theme={theme} style={{padding:0,overflow:"hidden"}}>
        <ConcertCover src={CONCERT_IMG.blue} tag="UPCOMING" tagBg="rgba(255,255,255,.92)" tagColor="#0F172A" caption="London · The O2 Arena"/>
        <div style={{padding:14}}>
          <p style={{fontWeight:800,fontSize:13.5,color:baseText,lineHeight:1.3}}>Ariana Grande — The Eternal Sunshine Tour</p>
          <p style={{fontSize:11,color:subText,marginTop:6,fontWeight:600}}>August 15, 2026 · Doors 18:00</p>
          <button onClick={()=>setInfo(!info)} style={{marginTop:12,width:"100%",padding:"11px",borderRadius:12,border:`1.5px solid ${theme.accent}`,cursor:"pointer",background:info?theme.accent:theme.chip,color:info?(theme.dark?"#06121F":"#fff"):baseText,fontWeight:800,fontSize:12}}>{t.hub_ticketvenue}</button>
          {info&&(
            <div style={{marginTop:12}}>
              <div style={{background:theme.chip,borderRadius:12,padding:12,marginBottom:10}}>
                <p style={{fontWeight:800,fontSize:11,color:baseText,marginBottom:8}}>Ticket</p>
                <Row k="Type" v="VIP Soundcheck · e-ticket"/>
                <Row k="Block / Row" v="Block A1 · Row 12 · Seats 8-10"/>
                <Row k="Entry gate" v="Entrance C · Level 1"/>
                <div style={{marginTop:8,height:34,borderRadius:8,background:"repeating-linear-gradient(90deg,#0F172A 0 2px,#fff 2px 4px,#0F172A 4px 5px,#fff 5px 9px)"}}/>
                <p style={{fontSize:9,color:subText,fontWeight:700,textAlign:"center",marginTop:4,letterSpacing:2}}>SN-O2-2026-08-15-A1</p>
              </div>
              <div style={{background:theme.chip,borderRadius:12,padding:12}}>
                <p style={{fontWeight:800,fontSize:11,color:baseText,marginBottom:8}}>Venue instructions</p>
                <Row k="Getting there" v="Jubilee line → North Greenwich (3 min walk)"/>
                <Row k="Doors" v="18:00 · show 19:30"/>
                <Row k="Bag policy" v="Max A4 size · no large bags"/>
                <Row k="Age" v="U16 with adult · ID for VIP"/>
                <Row k="Box office" v="Collect VIP laminates at Gate C from 17:00"/>
              </div>
            </div>
          )}
        </div>
      </Card>

      {/* user-added upcoming */}
      {extraUpcoming.map((e,i)=>(
        <Card key={i} theme={theme} style={{padding:0,overflow:"hidden"}}>
          <ConcertCover src={e.img} tag="ADDED" tagBg={theme.accent} tagColor={theme.dark?"#06121F":"#fff"} caption={e.venue}/>
          <div style={{padding:14}}>
            <p style={{fontWeight:800,fontSize:13.5,color:baseText,lineHeight:1.3}}>{e.title}</p>
            <p style={{fontSize:11,color:subText,marginTop:6,fontWeight:600}}>{e.date}</p>
          </div>
        </Card>
      ))}

      <p style={{fontSize:13,fontWeight:800,color:subText,margin:"8px 0 10px"}}>{t.hub_past}</p>
      {history.map((e,i)=>(
        <Card key={i} theme={theme} style={{padding:0,overflow:"hidden",opacity:.95}}>
          <ConcertCover src={e.img} faded tag="DONE" tagBg="#16A34A" tagColor="#fff"/>
          <div style={{padding:14}}>
            <p style={{fontWeight:800,fontSize:12.5,color:baseText,lineHeight:1.3}}>{e.title}</p>
            <p style={{fontSize:11,color:subText,marginTop:4,fontWeight:600}}>{e.sub}</p>
          </div>
        </Card>
      ))}
    </div>
  );
}
function ConcertCover({src,tag,tagBg,tagColor,caption,faded=false}){
  return (
    <div style={{position:"relative",height:120,overflow:"hidden"}}>
      <img src={src} alt="" style={{width:"100%",height:"100%",objectFit:"cover",display:"block",filter:faded?"grayscale(.85) saturate(.35) brightness(1.05)":"none"}}/>
      <div style={{position:"absolute",inset:0,background:"linear-gradient(180deg,rgba(0,0,0,.05),rgba(0,0,0,.5))"}}/>
      {tag&&<span style={{position:"absolute",top:10,right:10,background:tagBg,color:tagColor,fontSize:9,fontWeight:800,padding:"3px 9px",borderRadius:20}}>{tag}</span>}
      {caption&&<span style={{position:"absolute",bottom:8,left:12,color:"#fff",fontWeight:800,fontSize:11,textShadow:"0 1px 4px rgba(0,0,0,.7)"}}>{caption}</span>}
    </div>
  );
}
function Row({k,v}){
  return <div style={{display:"flex",justifyContent:"space-between",gap:10,fontSize:10.5,padding:"3px 0"}}><span style={{fontWeight:800,color:"#475569",minWidth:84}}>{k}</span><span style={{textAlign:"right",fontWeight:600,color:"#0F172A"}}>{v}</span></div>;
}

